-- Spin wheel odds (hand-maintained; not generated by `game-db import`).
-- weight_ppm = parts per million, so 5000 = 0.5%. Active weights must total 1,000,000.
INSERT INTO spin_wheel_segments (segment_code, currency, amount, weight_ppm, is_jackpot, sort_order, active) VALUES
    ('coins-10',   'coins',   10, 400000, false, 1, true),
    ('coins-20',   'coins',   20, 250000, false, 2, true),
    ('gems-5',     'gems',     5, 120000, false, 3, true),
    ('coins-50',   'coins',   50, 100000, false, 4, true),
    ('gems-10',    'gems',    10,  70000, false, 5, true),
    ('coins-100',  'coins',  100,  55000, false, 6, true),
    ('jackpot',    'coins', 5000,   5000, true,  7, true)
ON CONFLICT (segment_code) DO UPDATE SET
    currency = EXCLUDED.currency, amount = EXCLUDED.amount, weight_ppm = EXCLUDED.weight_ppm,
    is_jackpot = EXCLUDED.is_jackpot, sort_order = EXCLUDED.sort_order, active = EXCLUDED.active;

DO $$
DECLARE total bigint;
BEGIN
    SELECT coalesce(sum(weight_ppm), 0) INTO total FROM spin_wheel_segments WHERE active;
    IF total <> 1000000 THEN
        RAISE EXCEPTION 'spin_wheel_segments active weights sum to %, want 1000000', total;
    END IF;
END $$;
